/// カレンダー招待 (ICS) のセキュリティ検査。
pub mod calendar_guard;
pub mod css_sanitizer;
/// HTML スマグリング検出 (Blob/data: URI 経由のペイロード組み立て)。
pub mod html_smuggling;
/// ZIP Slip 攻撃防止 (Zenn Round5 P0)。
/// ファイルマジックバイト検証 — 拡張子偽装検出 (Qiita/Zenn Round5 P2)。
pub mod magic_bytes;
/// 添付ファイルメタデータ漏洩検出 (Round7 P1)。
pub mod metadata_check;
/// SVG 添付攻撃の検出 (2025-2026 に急増した主要ベクタ)。
pub mod svg_guard;

// ============================================================================
// 添付ファイル検査
// ============================================================================

/// 添付ファイル 1 件の検査結果。
#[derive(Debug, Clone, serde::Serialize)]
pub struct AttachmentScan {
    /// ファイル名 (Content-Disposition 由来)。
    pub filename: String,
    /// 宣言された MIME タイプ (詐称されうる)。
    pub declared_mime: String,
    /// サイズ (bytes)。
    pub size_bytes: u64,
    /// 検出されたリスク (人間可読)。
    pub risks: Vec<String>,
    /// 実行リスクがあるか。
    ///
    /// 危険拡張子 / MIME 偽装 / polyglot / SVG のスクリプト実行のいずれか。
    /// **メタデータ検出のみの場合は false** — 作成者情報や GPS はプライバシー
    /// 上の通知であって、開いた瞬間にコードが走るわけではないため。
    pub is_dangerous: bool,
    /// 暗号化フラグ付きエントリを含む ZIP ベースファイルか (D1251)。
    ///
    /// 「パスワード付き ZIP + 本文でパスワード案内」は解凍・検査を
    /// 回避する定番の手口 (Sublime Security の検知ルールと同型)。
    /// 単体では警告どまりだが、本文側の文言との相関で警告を上げる。
    pub is_encrypted: bool,
    /// 入れ子メール添付 (.eml/message/rfc822) の内側 `From:` の値 (D1279)。
    ///
    /// 外側メールの認証結果 (SPF/DKIM/DMARC) は内側に及ばない —
    /// 内側差出人の自称は無保証であり、受信側ドメインを騙る
    /// 内部偽装の代表的経路 (IRONSCALES 2026-01 観測)。
    pub inner_sender: Option<String>,
    /// 入れ子メール添付の内側 `Subject:` の値 (D1279)。
    pub inner_subject: Option<String>,
}

/// メール全体から添付を取り出し、実装済みの各検出器にかける。
///
/// # なぜこの関数が必要か
///
/// `kaname-render` には添付検査が揃っている
/// (`magic_bytes::check_mime_mismatch` / `detect_polyglot` /
/// `is_dangerous_windows_attachment`、`metadata_check::detect_metadata_risks`、
/// `svg_guard::scan_svg`)。しかし `parse()` が構築する `AttachmentHeader` は
/// **バイト列を保持しておらず** (`part.contents().len()` でサイズだけ取って
/// 中身を捨てている)、これらの検出器に渡す経路が存在しなかった。
/// 結果として添付検査は一つも動いていなかった。
///
/// `AttachmentHeader` にバイト列を足す設計は採らない。全添付をメモリに
/// 常駐させることになり大きな添付で不利なため、**バイトはこのクレート内で
/// 完結させ**、検査結果だけを返す。
///
/// 生 RFC5322 メールから MLS エンベロープパート
/// (`Content-Type: application/mls-envelope+cbor`) の復号済みボディを
/// すべて取り出す (D1 Phase 4 — 受信経路)。
///
/// `Content-Disposition: attachment` に限らず全 MIME パートを走査する —
/// 相手クライアントがインラインで挿入する可能性があるため。
/// `mail-parser` は `msg.parts` に全パートをフラットに持ち、入れ子の
/// message/rfc822 は `PartType::Message` として現れるため再帰で潜る。
/// transfer-encoding は復号済みの `contents()` を返す。
#[must_use]
pub fn extract_mls_envelopes(raw: &[u8]) -> Vec<Vec<u8>> {
    extract_parts_by_media_type(raw, "application", "mls-envelope+cbor")
}

/// MLS KeyPackage 添付の Content-Type (D1 Phase 3)。
/// 自分の KeyPackage を相手に手渡しする際の MIME タイプ —
/// エンベロープ (`application/mls-envelope+cbor`) は CBOR だが、
/// KeyPackage は TLS シリアライズ済みのためサフィックスを付けない。
pub const MLS_KEY_PACKAGE_MIME: &str = "application/mls-key-package";

/// `application/mls-key-package` パートの内容を取り出す。
///
/// 相手の KeyPackage が添付で届いた際 (Phase 3 配送経路)、
/// `kp_cache` 投入のために抽出する。転送符号化はデコード済み。
#[must_use]
pub fn extract_mls_key_packages(raw: &[u8]) -> Vec<Vec<u8>> {
    extract_parts_by_media_type(raw, "application", "mls-key-package")
}

/// 指定 Content-Type のパート内容を multipart を再帰走査して取り出す
/// (入れ子 `message/rfc822` を含む)。`Content-Disposition` を問わず
/// 全パートを検査するため、インライン挿入にも対応する。
fn extract_parts_by_media_type(raw: &[u8], ctype: &str, subtype: &str) -> Vec<Vec<u8>> {
    let Some(msg) = MessageParser::default().parse(raw) else {
        return Vec::new();
    };
    // 1 通のメールに収集する同種パート数の上限 (D126)。
    // 各エンベロープは MLS の into_group / 復号という実暗号処理を呼び、
    // 各 KeyPackage は TLS デシリアライズ + 署名検証を呼ぶため、
    // 無制限だと 1 通のメールで大量の暗号演算を強制できる (CPU DoS)。
    // 正規のメールで同種 MLS パートが 32 を超えることはない。
    const MAX_MATCHING_PARTS: usize = 32;
    // message/rfc822 の入れ子深度の上限 — パーサ自体の制限に依存せず
    // 自前で再帰深度を止めておかないと、極端に深い入れ子メールで
    // スタックを使い切り得る (D130)。正規の転送入れ子は数段まで。
    const MAX_NESTED_DEPTH: usize = 16;
    fn collect(
        part: &mail_parser::MessagePart<'_>,
        ctype: &str,
        subtype: &str,
        out: &mut Vec<Vec<u8>>,
        depth: usize,
    ) {
        if out.len() >= MAX_MATCHING_PARTS || depth > MAX_NESTED_DEPTH {
            return;
        }
        let matched = part
            .content_type()
            .map(|ct| {
                ct.ctype().eq_ignore_ascii_case(ctype)
                    && ct
                        .subtype()
                        .is_some_and(|s| s.eq_ignore_ascii_case(subtype))
            })
            .unwrap_or(false);
        if matched {
            out.push(part.contents().to_vec());
        }
        if let mail_parser::PartType::Message(sub) = &part.body {
            for p in &sub.parts {
                collect(p, ctype, subtype, out, depth + 1);
            }
        }
    }
    let mut out = Vec::new();
    for part in &msg.parts {
        collect(part, ctype, subtype, &mut out, 0);
    }
    out
}

/// # DoS 対策
///
/// 1 添付あたり検査するのは先頭 10 MB まで。それを超える部分は読まない。
#[must_use]
pub fn scan_attachments(raw: &[u8]) -> Vec<AttachmentScan> {
    let Some(msg) = MessageParser::default().parse(raw) else {
        return Vec::new();
    };

    let mut out = Vec::new();
    for part in msg.attachments() {
        let filename = part.attachment_name().unwrap_or("unnamed").to_string();
        let declared_mime = part
            .content_type()
            .map(|ct| {
                let main = ct.ctype();
                match ct.subtype() {
                    Some(sub) => format!("{main}/{sub}"),
                    None => main.to_string(),
                }
            })
            .unwrap_or_else(|| "application/octet-stream".to_string());

        out.push(scan_attachment_bytes(
            &filename,
            &declared_mime,
            part.contents(),
        ));
    }
    out
}

/// メール全体が MLS エンベロープ (`application/mls-envelope+cbor`) を
/// 含むかを判定する。ルートパートを含む全 MIME パートを検査するため、
/// 添付扱いされない本文直下のエンベロープも検出できる。
/// `kaname-jmap::BodyPart::is_mls_envelope` と同じ判定基準。
#[must_use]
pub fn is_mls_message(raw: &[u8]) -> bool {
    const MLS_MIME: &str = "application/mls-envelope+cbor";
    let Some(msg) = MessageParser::default().parse(raw) else {
        return false;
    };
    msg.parts.iter().any(|part| {
        part.content_type().is_some_and(|ct| {
            format!("{}/{}", ct.ctype(), ct.subtype().unwrap_or_default())
                .eq_ignore_ascii_case(MLS_MIME)
        })
    })
}

/// vCard の外部参照プロパティを検査する (D1268)。
///
/// RFC 6350 の URI 値を取るプロパティ — `PHOTO`/`LOGO`/`SOUND`/`SOURCE`/
/// `URL`/`GEO`/`IMPP`/`ORG-DIRECTORY` — はインポート・表示時にリモートから
/// フェッチされ得る。値部が http(s)/ftp で始まる行を検出する
/// (`data:` inline 埋め込みや `CID:` 参照は対象外)。
fn detect_vcard_external_refs(text: &str) -> Vec<String> {
    const URI_PROPS: &[&str] =
        &["PHOTO", "LOGO", "SOUND", "SOURCE", "URL", "GEO", "IMPP", "ORG-DIRECTORY"];
    let mut out = Vec::new();
    for raw in text.lines() {
        if raw.starts_with([' ', '\t']) {
            continue; // 継続行
        }
        let line = raw.trim();
        let Some((head, value)) = line.split_once(':') else { continue };
        let prop = head
            .split(';')
            .next()
            .map(str::trim)
            .unwrap_or("")
            .to_ascii_uppercase();
        // `ORG-DIRECTORY` 等のグループ接頭辞 (X.UID 等) は許容 — prop が
        // ドット付きなら末尾の名前だけを見る。
        let prop = prop.rsplit('.').next().unwrap_or(prop.as_str());
        if !URI_PROPS.contains(&prop) {
            continue;
        }
        let uri_val = value.trim();
        let lower_val = uri_val.to_ascii_lowercase();
        // 実際にリモートを参照するスキームのみ — `VALUE=URI` でも
        // `data:` 埋め込み・`CID:` 参照は外部フェッチではない。
        if lower_val.starts_with("http") || lower_val.starts_with("ftp:") {
            out.push(format!("{prop} が外部 URI を参照: {uri_val}"));
        }
    }
    out
}

/// 1 添付分のバイト列を各検出器にかける。
///
/// `scan_attachments` (メール全体) と、JMAP でダウンロードした単一 blob の
/// 両方から使える共通ロジック。検査は先頭 10 MB まで (DoS 対策)。
#[must_use]
pub fn scan_attachment_bytes(filename: &str, declared_mime: &str, full: &[u8]) -> AttachmentScan {
    const MAX_SCAN_BYTES: usize = 10 * 1024 * 1024;
    let size_bytes = full.len() as u64;
    let bytes = &full[..full.len().min(MAX_SCAN_BYTES)];

    let mut risks = Vec::new();
    let mut is_dangerous = false;
    let mut inner_sender: Option<String> = None;
    let mut inner_subject: Option<String> = None;

    // 1. Windows で危険な拡張子 (.lnk / .docm / .scr / .exe 等) と
    //    双方向制御文字 (RTLO) を使った拡張子表示反転 (D166)
    if magic_bytes::is_dangerous_windows_attachment(filename) {
        risks.push(format!("危険な拡張子です: {filename}"));
        is_dangerous = true;
    }
    if magic_bytes::has_bidi_override_filename(filename) {
        risks.push(
            "ファイル名に双方向テキスト制御文字 (RTLO 等) が含まれており、拡張子の表示が反転して実際の形式を隠している可能性があります"
                .to_string(),
        );
        is_dangerous = true;
    }

    // 1.5 ファイル名の異常形状 (D1265) — 制御文字注入 / 末尾 `.`/` ` /
    //     キリル・ギリシャ文字のホモグリフ混在。末尾の `.`/` ` は
    //     Windows が保存時に除去するため、除去後の名前でも危険拡張子を
    //     再評価する (表示名と実ファイル名の食い違い)。
    for anomaly in magic_bytes::filename_anomalies(filename) {
        risks.push(
            match anomaly {
                "control_chars" => "ファイル名に制御文字 (CR/LF/TAB 等) が含まれています — ツールごとに名前の解釈がずれ、表示と実際の保存名が食い違う可能性があります".to_string(),
                "trailing_dot_or_space" => "ファイル名がピリオドまたは空白で終わっています — Windows は保存時に末尾を除去するため、表示名と実ファイル名が一致しません".to_string(),
                "ads_stream" => "ファイル名にコロンが含まれています — Windows の Alternate Data Stream として別名に書き込まれる格納先偽装の可能性があります".to_string(),
                _ => "ファイル名にキリル文字/ギリシャ文字がラテン文字と混在しています — 見た目で実際のファイル名を偽装している可能性があります".to_string(),
            },
        );
    }
    let cleaned_name = filename.trim_end_matches(['.', ' ']);
    if cleaned_name != filename && magic_bytes::is_dangerous_windows_attachment(cleaned_name) {
        risks.push(format!(
            "ファイル名末尾のピリオド/空白が除去されると {cleaned_name} になります — 危険な拡張子です"
        ));
        is_dangerous = true;
    }

    // 2. 宣言 MIME と実体の不一致 (実行ファイルを画像等に偽装)
    if let Some(mismatch) = magic_bytes::check_mime_mismatch(declared_mime, bytes) {
        risks.push(format!(
            "MIME 偽装の疑い: {} と宣言されていますが実体は {} です",
            mismatch.declared, mismatch.detected
        ));
        is_dangerous = true;
    }

    // 3. Polyglot (画像/PDF としても ZIP としても有効)
    if let Some((a, b)) = magic_bytes::detect_polyglot(bytes) {
        risks.push(format!(
            "Polyglot ファイルです ({a} と {b} の両方として有効)"
        ));
        is_dangerous = true;
    }

    // 4. SVG のスクリプト実行 / XXE / プロンプト注入
    if let Ok(text) = std::str::from_utf8(bytes) {
        if svg_guard::looks_like_svg(text) {
            let scan = svg_guard::scan_svg(text);
            // 実行リスク以外の注意喚起 (外部参照・非表示要素) も risks に
            // 載せる — 実行リスクだけの条件で丸ごと捨てると、回避の兆候
            // が利用者に見えないままだった (D1256)。
            for r in &scan.risks {
                risks.push(format!("SVG のリスク: {r:?}"));
            }
            if !scan.safe_as_attachment {
                is_dangerous = true;
            }
        }
    }

    // 5. カレンダー招待 (.ics) の検査 (CalPhishing)
    if let Ok(text) = std::str::from_utf8(bytes) {
        let is_ics = filename.to_ascii_lowercase().ends_with(".ics")
            || declared_mime.to_ascii_lowercase().contains("text/calendar")
            || text.contains("BEGIN:VCALENDAR");
        if is_ics {
            let scan = calendar_guard::CalendarGuard.analyze(text);
            if !matches!(scan.risk_level, calendar_guard::CalendarRiskLevel::Safe) {
                for r in &scan.risks {
                    risks.push(format!("カレンダー招待のリスク: {r:?}"));
                }
                // Danger のみ実行リスク扱い。Caution は注意喚起に留める。
                if matches!(scan.risk_level, calendar_guard::CalendarRiskLevel::Danger) {
                    is_dangerous = true;
                }
            }
        }
    }

    // 5.6 vCard (.vcf) の外部参照 (D1268) — PHOTO/LOGO/SOUND/SOURCE/URL
    //     等の http/ftp 値はインポート・表示時にリモートから
    //     フェッチされる (ICS `ATTACH;VALUE=URI`、message/external-body と
    //     同型の死角)。vCard には連絡先の体裁で任意 URL を載せられる。
    if let Ok(text) = std::str::from_utf8(bytes) {
        let lower_name = filename.to_ascii_lowercase();
        let is_vcf = lower_name.ends_with(".vcf")
            || lower_name.ends_with(".vcard")
            || declared_mime.to_ascii_lowercase().contains("vcard")
            || text.contains("BEGIN:VCARD");
        if is_vcf {
            for r in detect_vcard_external_refs(text) {
                risks.push(format!("vCard 添付のリスク: {r}"));
            }
        }
    }

    // 5.5 HTML 添付のスマグリング検査 (D1248 — ClickFix/FileFix)
    //     「.html を開かせる」は本文側の HTML スマグリングと別経路 —
    //     ブラウザで開いた時点で実行されるため、本文だけを検査していても
    //     添付は素通りだった。中身が HTML なら拡張子を問わず走査する
    //     (text/plain 等への偽装はあり得る)。
    if let Ok(text) = std::str::from_utf8(bytes) {
        let mut boundary = text.len().min(4096);
        while boundary > 0 && !text.is_char_boundary(boundary) {
            boundary -= 1;
        }
        let head = text[..boundary].to_ascii_lowercase();
        let lower_name = filename.to_ascii_lowercase();
        let is_html_attachment = lower_name.ends_with(".html")
            || lower_name.ends_with(".htm")
            || declared_mime.to_ascii_lowercase().contains("text/html")
            || head.contains("<html")
            || head.contains("<!doctype html")
            || head.contains("<script");
        if is_html_attachment {
            let scan = html_smuggling::HtmlSmugglingDetector.analyze(text);
            if !matches!(scan.risk, html_smuggling::SmugglingRisk::Clean) {
                risks.push(format!("HTML 添付のリスク: {}", scan.message));
                for s in &scan.signals {
                    risks.push(format!("  検出シグナル: {s:?}"));
                }
                // High/Critical は実行リスク扱い。Caution は注意喚起に留める。
                if matches!(
                    scan.risk,
                    html_smuggling::SmugglingRisk::High | html_smuggling::SmugglingRisk::Critical
                ) {
                    is_dangerous = true;
                }
            }
        }
    }

    // 5.7 ネストしたメール添付 (.eml/.msg) — 注意喚起 (D1250)。
    //     内側の件名・差出人は外側と無関係に偽装できる。
    if magic_bytes::is_nested_email_attachment(filename, declared_mime) {
        risks.push(
            "メール形式の添付です (.eml/.msg) — 内側の件名・差出人は外側と無関係に偽装でき、\
             ゲートウェイ検査を回避する代表的な手口として観測されています。\
             開封後の内容が外側の文脈と一致するか確認してください"
                .to_string(),
        );
        // D1279: 内側ヘッダをそのまま提示 — 差出人の自称が外側の
        //   認証で裏付けられないことを可視化する (IRONSCALES 2026-01:
        //   空本文 + .eml 添付 + 内側 From が受信者の経理部門を騙る)。
        let (f, s) = extract_nested_email_identity(bytes);
        if let Some(f) = &f {
            risks.push(format!(
                "内側メールの差出人: {f} — 外側メールの SPF/DKIM/DMARC 認証は内側に及びません"
            ));
        }
        if let Some(s) = &s {
            risks.push(format!("内側メールの件名: {s}"));
        }
        inner_sender = f;
        inner_subject = s;
    }

    // 5.8 特殊な message/* サブタイプ (D1266) — external-body は表示時に
    //     リモートから中身をフェッチし、partial はペイロードを断片化して
    //     各片の検査を素通りする。delivery-status/disposition-notification
    //     は解析パイプラインの死角として観測されている。
    if magic_bytes::is_exotic_message_subtype(declared_mime) {
        risks.push(format!(
            "特殊な message/* 添付です ({declared_mime}) — 外部参照や断片分割により内容がスキャンを素通りする可能性があります"
        ));
    }

    // 6. メタデータ (作成者/GPS 等)。プライバシー通知であり実行リスクではない。
    for r in metadata_check::detect_metadata_risks(filename, bytes) {
        risks.push(format!("メタデータが含まれます: {r:?}"));
    }

    // 7. 疑似署名添付 (D239) — `signature.asc`/`smime.p7s` 等の
    //    「署名済み」を装う添付は、署名検証なしの体裁で
    //    信頼を獲得しながら実行形式を内包し得る (S/MIME 偽装)。
    if is_pseudo_signature_attachment(filename) {
        risks.push(
            "署名らしき添付 (signature.asc/smime.p7s 等) — 検証なしの体裁で \
             信頼を装う可能性があります"
                .to_string(),
        );
    }

    // 7.5 暗号化フラグ付き ZIP エントリ (D1251)。
    //      パスワード保護は中身の検査を不可能にする — 添付自体は危険と
    //      断定せず risks に通知し、本文のパスワード記載との相関は
    //      kaname-ui 側 (`analyze_raw_email`) で警告する。
    let mut is_encrypted = false;
    if magic_bytes::is_zip_file(filename, bytes) && magic_bytes::zip_has_encrypted_entries(bytes) {
        is_encrypted = true;
        risks.push(
            "ZIP に暗号化フラグ付きエントリがあります (パスワード保護) — \
             内容物をスキャンできません。本文にパスワードが書かれている場合は特に注意してください"
                .to_string(),
        );
    }

    // 7.7 PDF の静的検査 (D1253 — PDF 添付急増への対応)
    //     実行・自動起動系 (/JavaScript・/OpenAction・/AA・/Launch) は
    //     実行リスク。/EmbeddedFile 等の運搬要素は注意喚起どまり。
    //     /Encrypt は ZIP と同じく「中身を検査できない」経路 —
    //     is_encrypted に設定して本文パスワードとの相関 (D1251) に乗せる。
    if magic_bytes::is_pdf_file(filename, bytes) {
        if magic_bytes::pdf_is_encrypted(bytes) {
            is_encrypted = true;
            risks.push(
                "PDF が暗号化されています (パスワード保護) — \
                 内容物をスキャンできません。本文にパスワードが書かれている場合は特に注意してください"
                    .to_string(),
            );
        }
        for marker in magic_bytes::pdf_active_markers(bytes) {
            risks.push(format!("PDF に実行・自動起動系の要素があります ({marker})"));
            is_dangerous = true;
        }
        for marker in magic_bytes::pdf_embedded_markers(bytes) {
            risks.push(format!(
                "PDF に外部連携・内蔵ペイロード系の要素があります ({marker})"
            ));
        }
    }

    AttachmentScan {
        filename: filename.to_string(),
        declared_mime: declared_mime.to_string(),
        size_bytes,
        risks,
        is_dangerous,
        is_encrypted,
        inner_sender,
        inner_subject,
    }
}


#[test]
fn scan_は売機印を検出する() {
    let g1 = b"From: a@b
X-Gulliver-Id: 1

x";
    let n1 = b"From: a@b
X-Nextage-Trace: 1

x";
    let a1 = b"From: a@b
X-Autobacs-Ref: 1

x";
    let y1 = b"From: a@b
X-YellowHat-Id: 1

x";
    let c1 = b"From: a@b
X-Carvana-Order: 1

x";
    let m1 = b"From: a@b
X-CarMax-Appraisal: 1

x";
    let w1 = b"From: a@b
X-Webike-Ship: 1

x";
    let k1 = b"From: a@b
X-Kavak-Deal: 1

x";
    assert!(has_cartrade_marks(g1));
    assert!(has_cartrade_marks(n1));
    assert!(has_cartrade_marks(a1));
    assert!(has_cartrade_marks(y1));
    assert!(has_cartrade_marks(c1));
    assert!(has_cartrade_marks(m1));
    assert!(has_cartrade_marks(w1));
    assert!(has_cartrade_marks(k1));
    let clean = b"From: a@b
X-Other: 1

body";
    assert!(!has_cartrade_marks(clean));
}

